import { Component, Input, Optional } from '@angular/core';
import { AccordionPanelComponent } from '../accordion-panel/accordion-panel.component';
import { AccordionConfig } from '../accordion.config';

@Component({
	selector: 'espd-accordion',
	template: `<ng-content />`,
	host: {
		style: 'display: block'
	}
})
export class AccordionComponent {
	/** turn on/off animation */
	@Input() isAnimated: boolean = true;

	/** if `true` expanding one item will close all others */
	@Input() closeOthers: boolean = true;

	protected panels: AccordionPanelComponent[] = [];

	constructor(@Optional() config?: AccordionConfig) {
		Object.assign(this, config);
	}

	public closeOtherPanels(openGroup: AccordionPanelComponent): void {
		if (!this.closeOthers) {
			return;
		}

		this.panels.forEach((panel: AccordionPanelComponent) => {
			if (panel !== openGroup) {
				panel.isOpen = false;
			}
		});
	}

	public addPanel(panel: AccordionPanelComponent): void {
		panel.isAnimated = this.isAnimated;
		this.panels.push(panel);
	}

	public removePanel(panel: AccordionPanelComponent): void {
		const index = this.panels.indexOf(panel);
		if (index !== -1) {
			this.panels.splice(index, 1);
		}
	}
}
